/**
 * repair-backfill-chunks.ts
 *
 * One-shot repair: finds all backfill-cid:* rows that are missing David-scoped
 * conversation_chunk embeddings and re-embeds them.
 *
 * Arms A and B are always regenerated by reembedConversationMemory, but the
 * hash-match guard means they only call OpenAI when the content has changed
 * (i.e. almost never for backfill rows).  Only the missing chunks hit the API.
 *
 * Strategy: process rows in parallel batches of BATCH_SIZE with BATCH_PAUSE_MS
 * between batches to stay within OpenAI rate limits.
 *
 * Usage:
 *   npx tsx server/scripts/repair-backfill-chunks.ts
 *   npx tsx server/scripts/repair-backfill-chunks.ts --dry-run
 */

import { neon } from '@neondatabase/serverless';
import { reembedConversationMemory } from './reembed-memory';

const DRY_RUN    = process.argv.includes('--dry-run');
const BATCH_SIZE = 5;      // rows in parallel per batch
const BATCH_PAUSE_MS = 500; // ms between batches
const DAVID_USER_ID = '49847136';

function sleep(ms: number) { return new Promise(r => setTimeout(r, ms)); }

const G = (s: string) => `\x1b[32m${s}\x1b[0m`;
const R = (s: string) => `\x1b[31m${s}\x1b[0m`;
const Y = (s: string) => `\x1b[33m${s}\x1b[0m`;
const B = (s: string) => `\x1b[34m${s}\x1b[0m`;

async function main() {
  const dbUrl = process.env.NEON_SHARED_DATABASE_URL ?? process.env.DATABASE_URL;
  if (!dbUrl) throw new Error('NEON_SHARED_DATABASE_URL or DATABASE_URL not set');
  const sql = neon(dbUrl);

  console.log(B('\n══ Backfill Chunk Repair ══\n'));
  if (DRY_RUN) console.log(Y('  --dry-run: no embeddings will be generated\n'));

  // Find rows missing David-scoped chunk:0 embedding
  const rows = await sql`
    SELECT cm.id, length(cm.content) AS content_len
    FROM conversation_memories cm
    WHERE EXISTS (SELECT 1 FROM unnest(cm.tags) t WHERE t LIKE 'backfill-cid:%')
      AND length(cm.content) > 4500
      AND NOT EXISTS (
        SELECT 1 FROM memory_embeddings me
        WHERE me.memory_id   = (cm.id::text || ':chunk:0')
          AND me.memory_type = 'conversation_chunk'
          AND me.user_id     = ${DAVID_USER_ID}
      )
    ORDER BY content_len ASC
  ` as Array<{ id: string; content_len: number }>;

  console.log(`  Rows needing chunk repair: ${rows.length}\n`);
  if (rows.length === 0) {
    console.log(G('  ✓ Nothing to repair — all backfill rows have chunk embeddings.\n'));
    return;
  }

  let done = 0, failed = 0;
  const startTime = Date.now();

  for (let i = 0; i < rows.length; i += BATCH_SIZE) {
    const batch = rows.slice(i, i + BATCH_SIZE);
    const pct = Math.round((i / rows.length) * 100);

    await Promise.allSettled(
      batch.map(async (r) => {
        const expectedChunks = Math.ceil((r.content_len - 900) / 3600);
        if (DRY_RUN) {
          console.log(`  [${pct}%] WOULD REPAIR  ${r.id.slice(0, 8)}…  len=${r.content_len}  chunks=${expectedChunks}`);
          done++;
          return;
        }
        try {
          await reembedConversationMemory(r.id, DAVID_USER_ID);
          done++;
          console.log(G(`  [${pct}%] REPAIRED  ${r.id.slice(0, 8)}…  len=${r.content_len}  chunks=${expectedChunks}`));
        } catch (err: any) {
          failed++;
          console.error(R(`  [${pct}%] FAILED  ${r.id.slice(0, 8)}…: ${err?.message ?? err}`));
        }
      })
    );

    if (i + BATCH_SIZE < rows.length) await sleep(BATCH_PAUSE_MS);
  }

  const elapsed = Math.round((Date.now() - startTime) / 1000);
  console.log(`\n  Done in ${elapsed}s — repaired: ${done}, failed: ${failed}`);

  if (failed > 0) {
    console.error(R(`\n  ✗ ${failed} row(s) failed — re-run to retry.\n`));
    process.exit(1);
  }
  console.log(G(`\n  ✓ All ${done} rows repaired.\n`));
}

// Entry point guard
const scriptName = 'repair-backfill-chunks';
if (process.argv[1]?.includes(scriptName)) {
  main().catch((err: any) => {
    console.error(R('FATAL: ' + (err?.message ?? err)));
    process.exit(1);
  });
}
